select *
from b_retry_main_log
where retry_status = 1
and incr_id >= #{minId}
order by incr_id asc limit 500;

select incr_id
from b_retry_main_log
where retry_status = 4
  and retry_service = #{service}
  and retry_method = #{method}
order by incr_id asc limit 1;

select *
from b_retry_main_log
where retry_status = 4
  and retry_service = #{service}
  and retry_method = #{method}
  and incr_id >= #{minId}
order by incr_id asc limit #{pageSize};
